window.docContents[244].resolve({"/Elementary-Functions/___4___47-Approximations/#LMLF-___-DLMF-with-Lean--Elementary-Functions--___4___47-Approximations--___4___47-Approximations--___4___47_LPAR_i_RPAR_-Chebyshev-Series-Expansions":{"contents":"Clenshaw (1962) and Luke (1975, Chapter 3) give 20D coefficients for\nln, exp, sin, cos, tan, cot, arcsin, arctan, and arcsinh.\nSchonfelder (1980) gives 40D coefficients for sin, cos, and tan.\nThe source subsection is a reference to these coefficient sets, not a\ndisplayed universal approximation identity.\n\n","context":"LMLF · DLMF with Lean\u0009Elementary Functions\u0009§4.47 Approximations\u0009§4.47 Approximations","header":"§4.47(i) Chebyshev-Series Expansions","id":"/Elementary-Functions/___4___47-Approximations/#LMLF-___-DLMF-with-Lean--Elementary-Functions--___4___47-Approximations--___4___47-Approximations--___4___47_LPAR_i_RPAR_-Chebyshev-Series-Expansions"}});